import runpy
import sys
s = runpy.run_path(sys.argv[1])
f=s['countdown_step']
a={'remaining':2,'tag':'x'}
assert f(a)=={'remaining':1,'tag':'x','done':False}
assert a=={'remaining':2,'tag':'x'}
assert f({'remaining':0})=={'remaining':0,'done':True}
assert f({'remaining':1,'done':False})=={'remaining':0,'done':True}
for value in [True,False,-1,1.5,'3',None]:
 try: f({'remaining':value})
 except ValueError: pass
 else: raise AssertionError('invalid remaining accepted')
try: f({})
except ValueError: pass
else: raise AssertionError('missing remaining accepted')
